import type { CartLine } from '#shared/types/cart'
import type { Quote } from '#server/utils/quote'

export interface Order extends Quote {
  id: string
}

const orders = new Map<string, { order: Order, lines: CartLine[] }>()

export function saveOrder(lines: CartLine[], quote: Quote): Order {
  const order: Order = { id: crypto.randomUUID(), ...quote }
  orders.set(order.id, { order, lines })
  return order
}

export function findOrder(id: string) {
  return orders.get(id)
}
